List<Integer> ints = List.of(1, 2, 3);
// List<Number> nums = ints; // COMPILE ERROR: invariant
List<? extends Number> nums = ints; // OK: covariant read-only view
Number n = nums.get(0); // OK: every member is a Number
// nums.add(42); // COMPILE ERROR: might be List<Double>

List<Object> objs = new ArrayList<>();
List<? super Integer> sink = objs; // OK: contravariant write-only view
sink.add(42); // OK: 42 is an Integer, fits any supertype bucket
// Integer x = sink.get(0); // COMPILE ERROR: only know it is Object

final class Transfers {
  // Producer: src only gives values out -> extends.
  // Consumer: dst only takes values in -> super.
  static <T> void copy(List<? super T> dst, List<? extends T> src) {
    for (T t : src) dst.add(t); // T is the bridge: read as T, write as T
  }
}

// Exact type: read AND write the same list -> no wildcard.
static <T> void swap(List<T> list, int i, int j) {
  T tmp = list.get(i);
  list.set(i, list.get(j));
  list.set(j, tmp);
}

// Wildcard: T appears once, only for subtyping flexibility. Preferred.
boolean containsAll(Collection<?> other);
void addAll(Collection<? extends E> src);

// Named param: T relates two positions. Wildcard cannot express this.
static <T> T pickFirst(List<T> list, T fallback) {
  return list.isEmpty() ? fallback : list.get(0);
}
// Anti-pattern: naming a variable you use once.
// <T extends E> void addAll(Collection<T> src) // works, but noisy

// Capture helper: public wildcard API, private generic implementation.
static void reverse(List<?> list) { reverseHelper(list); }
private static <T> void reverseHelper(List<T> list) {
  // Now T has a name, so get and set can correlate.
  for (int i = 0, j = list.size() - 1; i < j; i++, j--)
    swap(list, i, j);
}
